const strings = ['apple', 'banana', 'apple', 'orange', 'banana'];

console.log("Numbers (Set):", removeDuplicatesUsingSet(numbers)); // Output: [1, 2, 3, 4, 5]
console.log("Strings (Set):", removeDuplicatesUsingSet(strings)); // Output: ['apple', 'banana', 'orange']
```

### 2. Using `filter` and `indexOf` (Preserves order)

This method iterates through the array and keeps an element only if its first occurrence's index matches the current index. This is useful if you need to maintain the original order of the unique elements.

```javascript
/**
 * Removes duplicate elements from an array while preserving the order of first appearance.
 * @param {Array<any>} arr The input array which may contain duplicates.
 * @returns {Array<any>} A new array with duplicates removed, maintaining order.
 */
function removeDuplicatesUsingFilter(arr) {
  return arr.filter((item, index) => arr.indexOf(item) === index);
}

// Example Usage:
const data = [10, 5, 10, 20, 5, 30, 20];
console.log("Data (Filter):", removeDuplicatesUsingFilter(data)); // Output: [10, 5, 20, 30]
```

### 3. Using `reduce` (Alternative for order preservation)

This is another functional approach to achieve the same result as the `filter` method.

```javascript
/**
 * Removes duplicate elements from an array while preserving the order of first appearance using reduce.
 * @param {Array<any>} arr The input array which may contain duplicates.
 * @returns {Array<any>} A new array with duplicates removed, maintaining order.
 */
function removeDuplicatesUsingReduce(arr) {
  return arr.reduce((accumulator, currentItem) => {
    if (!accumulator.includes(currentItem)) {
      accumulator.push(currentItem);
    }
    return accumulator;
  }, []);
}

