Here is a JavaScript function to create a `debounce` utility. This is a very common and useful pattern for optimizing performance, especially in scenarios like handling rapid user input (e.g., search bars, window resizing).

```javascript
/**
 * Creates a debounced function that delays invoking `func` until after `wait` milliseconds
 * have elapsed since the last time the debounced function was invoked.
 *
 * @param {Function} func The function to debounce.
 * @param {number} wait The number of milliseconds to wait after the last invocation.
 * @returns {Function} Returns the new debounced function.
 */
function debounce(func, wait) {
    let timeoutId = null;

    /**
     * The debounced function that will be called repeatedly.
     * @param {...any} args Arguments passed to the original function.
     */
    return function(...args) {
        // 'this' context is preserved for the original function call
        const context = this;

        // Clear the previous timeout if it exists
        if (timeoutId) {
            clearTimeout(timeoutId);
        }

        // Set a new timeout
        timeoutId = setTimeout(() => {
            // Execute the original function with the correct context and arguments
            func.apply(context, args);
            timeoutId = null; // Clear the ID after execution
        }, wait);
    };
}

// --- Example Usage ---

// 1. The function we want to debounce (e.g., an expensive API call or DOM manipulation)
function handleSearchInput(searchTerm) {
    console.log(`Searching for: ${searchTerm}`);
}

// 2. Create a debounced version of the function, waiting 500ms
const debouncedSearch = debounce(handleSearchInput, 500);

console.log("Simulating rapid user input...");

// Simulate rapid calls within a short time frame
debouncedSearch("a");
debouncedSearch("ap");
debouncedSearch("app");

// Wait 1 second, then call again
setTimeout(() => {
    debouncedSearch("apple");
}, 1000);

// After this final call, the function will only execute once, 500ms after the last call.
```

