/**
 * Performs a deep clone of an object or value.
 *
 * This function handles plain objects, arrays, and primitive types.
 * It does not handle complex types like Date, RegExp, Map, Set, or circular references
 * for simplicity, but it works perfectly for standard JSON-safe data structures.
 *
 * @param {any} source The object or value to clone.
 * @returns {any} A deep clone of the source.
 */
function deepClone(source) {
    // 1. Handle primitive types and null
    if (source === null || typeof source !== 'object') {
        return source;
    }

    // 2. Handle Date objects
    if (source instanceof Date) {
        return new Date(source.getTime());
    }

    // 3. Handle Array objects
    if (Array.isArray(source)) {
        const clonedArray = [];
        for (let i = 0; i < source.length; i++) {
            clonedArray[i] = deepClone(source[i]);
        }
        return clonedArray;
    }

    // 4. Handle plain Objects
    if (typeof source === 'object') {
        const clonedObject = {};
        for (const key in source) {
            // Ensure we only copy own properties
            if (Object.prototype.hasOwnProperty.call(source, key)) {
                clonedObject[key] = deepClone(source[key]);
            }
        }
        return clonedObject;
    }

    // Fallback for any other unexpected object types (though covered above)
    return source;
}

