/**
 * Flattens a nested array into a single-level array.
 *
 * @param {Array<any>} arr The nested array to flatten.
 * @returns {Array<any>} A new, one-dimensional array containing all elements.
 */
function flattenArray(arr) {
  const flattened = [];

  for (const element of arr) {
    if (Array.isArray(element)) {
      // If the element is an array, recursively flatten it and push the results
      const subArray = flattenArray(element);
      flattened.push(...subArray);
