/**
 * Chunks an array into smaller arrays (chunks) of a specified size.
 *
 * @param {Array<T>} array The array to be chunked.
 * @param {number} n The desired size of each chunk. Must be a positive integer.
 * @returns {Array<Array<T>>} An array of arrays, where each inner array is a chunk of size n.
 * @template T
 */
function chunkArray(array, n) {
  if (n <= 0) {
    throw new Error("Chunk size (n) must be a positive integer.");
  }
  if (!Array.isArray(array)) {
    throw new Error("Input must be an array.");
  }

  const result = [];
  for (let i = 0; i < array.length; i += n) {
    // Use slice to extract a portion of the array starting at index i
    const chunk = array.slice(i, i + n);
    result.push(chunk);
  }

  return result;
}

