/**
 * Defines the structure for the input objects.
 * You can adjust this interface based on the actual structure of your data.
 */
interface DataItem {
  id: number;
  category: string;
  value: number;
}

/**
 * Defines the structure for the output, where keys are the grouping values
 * and values are arrays of objects belonging to that group.
 */
type GroupedArray<T extends Record<string, any>, K extends keyof T> = Record<T[K], T[]>;

/**
 * Groups an array of objects by the value of a specified key.
 *
 * @param arr The array of objects to group.
 * @param key The key in the objects to group by.
 * @returns An object where keys are the unique values of the specified key,
 *          and values are arrays of objects that share that key's value.
 *          Returns an empty object if the input array is empty.
 */
function groupArrayBy<T extends Record<string, any>, K extends keyof T>(
  arr: T[],
  key: K
): GroupedArray<T, K> {
  return arr.reduce((acc: GroupedArray<T, K>, currentItem: T): GroupedArray<T, K> => {
    const groupKey = currentItem[key];

    // Initialize the array for this group if it doesn't exist
    if (!acc[groupKey]) {
      acc[groupKey] = [];
    }

    // Push the current item into the appropriate group
    acc[groupKey].push(currentItem);

    return acc;
  }, {} as GroupedArray<T, K>);
