 * A class representing a Last-In, First-Out (LIFO) stack.
 * It provides methods to push an element onto the stack,
 * remove the top element (pop), and view the top element without removing it (peek).
 */
class Stack<T> {
  private items: T[];

    /**
     * Creates an instance of Stack with an empty array.
     */
    constructor() {
    }

    /**
     * Adds an element to the top of the stack.
     * @param element The element to be added to the stack.
     * @returns void
     */
    public push(element: T): void {
      this.items.push(element);
      console.log(`Pushed: ${element}`);
    }

    /**
     * Removes and returns the element at the top of the stack.
     * Returns undefined if the stack is empty.
     * @returns The element removed from the top of the stack, or undefined if the stack is empty.
     */
    public pop(): T | undefined {
      if (this.isEmpty()) {
        console.log("Error: Cannot pop from an empty stack.");
        return undefined;
      }
      const poppedItem = this.items.pop();
      console.log(`Popped: ${poppedItem}`);
      return poppedItem;
    }

    /**
     * Returns the element at the top of the stack without removing it.
     * Returns undefined if the stack is empty.
     * @returns The element at the top of the stack, or undefined if the stack is empty.
     */
    public peek(): T | undefined {
      if (this.isEmpty()) {
        console.log("Error: Cannot peek into an empty stack.");
        return undefined;
      }
      const topItem = this.items[this.items.length - 1];
      console.log(`Peeked: ${topItem}`);
      return topItem;
    }

    /**
     * Checks if the stack is empty.
     * @returns True if the stack contains no elements, false otherwise.
     */
    public isEmpty(): boolean {
      return this.items.length === 0;
    }

    /**
     * Returns the current number of elements in the stack.
     * @returns The number of elements in the stack.
     */
    public size(): number {
      return this.items.length;
    }

    /**
     * Returns a string representation of the current state of the stack.
     */
    public toString(): string {
        return `Stack contents (Top -> Bottom): [${this.items.join(', ')}]`;
    }
}

