/**
 * Checks if the parentheses, brackets, and braces in a string are balanced.
 *
 * @param s The input string to check.
 * @returns True if the parentheses are balanced, false otherwise.
 */
function areParenthesesBalanced(s: string): boolean {
    const stack: string[] = [];
    const map: { [key: string]: string } = {
        '(': ')',
        '[': ']',
        '{': '}'
    };

    for (const char of s) {
        // If the character is an opening bracket, push its corresponding closing bracket onto the stack
        if (map[char]) {
            stack.push(map[char]);
        } 
        // If the character is a closing bracket
        else if (Object.values(map).includes(char)) {
            // If the stack is empty, it means we found a closing bracket without a corresponding opener
            if (stack.length === 0) {
                return false;
            }

            // Pop the top element from the stack and check if it matches the current closing bracket
            const expectedCloser = stack.pop();
            if (char !== expectedCloser) {
                return false;
            }
        }
        // Ignore any other characters
    }

    // If the stack is empty at the end, all opening brackets were closed correctly
    return stack.length === 0;
}

// --- Examples ---

