const largest1 = findLargestNumber(array1);
console.log(`The largest number in [${array1}] is: ${largest1}`); // Output: 9

const array2: number[] = [-10, -5, -2, -8];
const largest2 = findLargestNumber(array2);
console.log(`The largest number in [${array2}] is: ${largest2}`); // Output: -2

const array3: number[] = [42];
const largest3 = findLargestNumber(array3);
console.log(`The largest number in [${array3}] is: ${largest3}`); // Output: 42

const arrayEmpty: number[] = [];
const largestEmpty = findLargestNumber(arrayEmpty);
console.log(`The largest number in [] is: ${largestEmpty}`); // Output: -Infinity
```

