/**
 * Finds the largest number in an array of numbers using Math.max.
 * 
 * @param numbers An array of numbers to search through.
 * @returns The largest number in the array, or -Infinity if the array is empty.
 */
function findLargestNumberConcise(numbers: number[]): number {
  if (numbers.length === 0) {
    return -Infinity;
  }

  return Math.max(...numbers);
}

// --- Examples for Concise Version ---
