 * @brief Copies a source string to a destination buffer without using strcpy.
 *
 * @param dest The destination character array (buffer) to copy into.
 * @param src The source string to copy from.
 * @return int Returns 0 on success, or -1 if the destination buffer is too small
 *             to hold the source string plus the null terminator.
 */
int custom_strncpy(char *dest, const char *src) {
    if (dest == NULL || src == NULL) {
        return -1; // Handle null pointers
    }

    int i = 0;
    // Iterate through the source string until the null terminator is found
    while (src[i] != '\0') {
        dest[i] = src[i];
        i++;
    }

    // Crucially, copy the null terminator to the destination
    dest[i] = '\0';

    return 0; // Success
